// TestRoleVariable tests variable parsing
func TestRoleVariable(t *testing.T) {
	var tests = []struct {
		title string
		in    string
		err   error
		out   Expression
	}{
		{
			title: "no curly bracket prefix",
			in:    "external.foo}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "invalid syntax",
			in:    `{{external.foo("bar")`,
			err:   trace.BadParameter(""),
		},
		{
			title: "invalid variable syntax",
			in:    "{{internal.}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "invalid dot syntax",
			in:    "{{external..foo}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "empty variable",
			in:    "{{}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "no curly bracket suffix",
			in:    "{{internal.foo",
			err:   trace.BadParameter(""),
		},
		{
			title: "too many levels of nesting in the variable",
			in:    "{{internal.foo.bar}}",
			err:   trace.BadParameter(""),
		},
		{
			title: "valid with brackets",
			in:    `{{internal["foo"]}}`,
			out:   Expression{namespace: "internal", variable: "foo"},
		},
		{
			title: "string literal",
			in:    `foo`,
			out:   Expression{namespace: LiteralNamespace, variable: "foo"},
		},
		{
			title: "external with no brackets",
			in:    "{{external.foo}}",
			out:   Expression{namespace: "external", variable: "foo"},
		},
		{
			title: "internal with no brackets",
			in:    "{{internal.bar}}",
			out:   Expression{namespace: "internal", variable: "bar"},
		},
		{
			title: "internal with spaces removed",
			in:    "  {{  internal.bar  }}  ",
			out:   Expression{namespace: "internal", variable: "bar"},
		},
		{
			title: "variable with prefix and suffix",
			in:    "  hello,  {{  internal.bar  }}  there! ",
			out:   Expression{prefix: "hello,  ", namespace: "internal", variable: "bar", suffix: "  there!"},
		},
		{
			title: "variable with local function",
			in:    "{{email.local(internal.bar)}}",
			out:   Expression{namespace: "internal", variable: "bar", transform: emailLocalTransformer{}},
		},
	}

	for _, tt := range tests {
		t.Run(tt.title, func(t *testing.T) {
			variable, err := Variable(tt.in)
			if tt.err != nil {
				assert.IsType(t, tt.err, err)
				return
			}
			assert.NoError(t, err)
			assert.Empty(t, cmp.Diff(tt.out, *variable, cmp.AllowUnexported(Expression{})))
		})
	}
}

// TestInterpolate tests variable interpolation
func TestInterpolate(t *testing.T) {
	type result struct {
		values []string
		err    error
	}
	var tests = []struct {
		title  string
		in     Expression
		traits map[string][]string
		res    result
	}{
		{
			title:  "mapped traits",
			in:     Expression{variable: "foo"},
			traits: map[string][]string{"foo": []string{"a", "b"}, "bar": []string{"c"}},
			res:    result{values: []string{"a", "b"}},
		},
		{
			title:  "mapped traits with email.local",
			in:     Expression{variable: "foo", transform: emailLocalTransformer{}},
			traits: map[string][]string{"foo": []string{"Alice <alice@example.com>", "bob@example.com"}, "bar": []string{"c"}},
			res:    result{values: []string{"alice", "bob"}},
		},
		{
			title:  "missed traits",
			in:     Expression{variable: "baz"},
			traits: map[string][]string{"foo": []string{"a", "b"}, "bar": []string{"c"}},
			res:    result{err: trace.NotFound("not found"), values: []string{}},
		},
		{
			title:  "traits with prefix and suffix",
			in:     Expression{prefix: "IAM#", variable: "foo", suffix: ";"},
			traits: map[string][]string{"foo": []string{"a", "b"}, "bar": []string{"c"}},
			res:    result{values: []string{"IAM#a;", "IAM#b;"}},
		},
		{
			title:  "error in mapping traits",
			in:     Expression{variable: "foo", transform: emailLocalTransformer{}},
			traits: map[string][]string{"foo": []string{"Alice <alice"}},
			res:    result{err: trace.BadParameter("")},
		},
		{
			title:  "literal expression",
			in:     Expression{namespace: LiteralNamespace, variable: "foo"},
			traits: map[string][]string{"foo": []string{"a", "b"}, "bar": []string{"c"}},
			res:    result{values: []string{"foo"}},
		},
	}

	for _, tt := range tests {
		t.Run(tt.title, func(t *testing.T) {
			values, err := tt.in.Interpolate(tt.traits)
			if tt.res.err != nil {
				assert.IsType(t, tt.res.err, err)
				assert.Empty(t, values)
				return
			}
			assert.NoError(t, err)
			assert.Empty(t, cmp.Diff(tt.res.values, values))
		})
	}
}

package utils

import (
	"regexp"
	"strings"

	"github.com/gravitational/trace"
)

// ContainsExpansion returns true if value contains
// expansion syntax, e.g. $1 or ${10}
func ContainsExpansion(val string) bool {
	return reExpansion.FindAllStringIndex(val, -1) != nil
}

// GlobToRegexp replaces glob-style standalone wildcard values
// with real .* regexp-friendly values, does not modify regexp-compatible values,
// quotes non-wildcard values
func GlobToRegexp(in string) string {
	return replaceWildcard.ReplaceAllString(regexp.QuoteMeta(in), "(.*)")
}

// ReplaceRegexp replaces value in string, accepts regular expression and simplified
// wildcard syntax, it has several important differeneces with standard lib
// regexp replacer:
// * Wildcard globs '*' are treated as regular expression .* expression
// * Expression is treated as regular expression if it starts with ^ and ends with $
// * Full match is expected, partial replacements ignored
// * If there is no match, returns not found error
func ReplaceRegexp(expression string, replaceWith string, input string) (string, error) {
	if !strings.HasPrefix(expression, "^") || !strings.HasSuffix(expression, "$") {
		// replace glob-style wildcards with regexp wildcards
		// for plain strings, and quote all characters that could
		// be interpreted in regular expression
		expression = "^" + GlobToRegexp(expression) + "$"
	}
	expr, err := regexp.Compile(expression)
	if err != nil {
		return "", trace.BadParameter(err.Error())
	}
	// if there is no match, return NotFound error
	index := expr.FindAllStringIndex(input, -1)
	if len(index) == 0 {
		return "", trace.NotFound("no match found")
	}
	return expr.ReplaceAllString(input, replaceWith), nil
}

// SliceMatchesRegex checks if input matches any of the expressions. The
// match is always evaluated as a regex either an exact match or regexp.
func SliceMatchesRegex(input string, expressions []string) (bool, error) {
	for _, expression := range expressions {
		if !strings.HasPrefix(expression, "^") || !strings.HasSuffix(expression, "$") {
			// replace glob-style wildcards with regexp wildcards
			// for plain strings, and quote all characters that could
			// be interpreted in regular expression
			expression = "^" + GlobToRegexp(expression) + "$"
		}

		expr, err := regexp.Compile(expression)
		if err != nil {
			return false, trace.BadParameter(err.Error())
		}

		// Since the expression is always surrounded by ^ and $ this is an exact
		// match for either a a plain string (for example ^hello$) or for a regexp
		// (for example ^hel*o$).
		if expr.MatchString(input) {
			return true, nil
		}
	}

	return false, nil
}

